/* ---------- Field extraction ---------- */
.fex{display:grid;grid-template-columns:minmax(0,1fr) clamp(240px,44%,316px);gap:14px;width:100%;container:fex/inline-size}
/* the document and the fields side by side while the component has room for both, whatever the screen; one above the other below that */
@container fex (max-width:560px){.fex-doc,.fex-side{grid-column:1/-1}}
.fex-doc{border-radius:18px;background:var(--chip);padding:var(--s-5);display:grid;place-items:center;min-width:0;position:relative;overflow:hidden}
/* the invoice is paper: white ink-on-paper in light mode, a dark document in dark mode */
.fex-pg{--pg:#fff;--pg-fg:#232323;--pg-mut:#6a6a6a;--pg-line:#e8e8e8;--pg-hl:var(--accent-mark,var(--accent));--pg-ring:var(--accent-mark,var(--accent));--pg-warn:232,155,20;--pg-wring:#e89b14;--pg-sh:0 1px 2px rgba(0,0,0,.08),0 8px 30px rgba(0,0,0,.08);
  width:min(330px,100%);background:var(--pg);color:var(--pg-fg);border-radius:6px;padding:var(--s-5) 22px;box-shadow:var(--pg-sh);font-size:12px;display:flex;flex-direction:column;gap:var(--s-2);position:relative}
:root[data-theme="dark"] .fex-doc{background:color-mix(in srgb,var(--chip) 40%,var(--stage))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .fex-doc{background:color-mix(in srgb,var(--chip) 40%,var(--stage))}}
:root[data-theme="dark"] .fex-pg{--pg:var(--raised);--pg-fg:var(--fg);--pg-mut:var(--muted);--pg-line:var(--line);--pg-warn:240,168,48;--pg-wring:#f0a830;--pg-sh:0 0 0 1px var(--line),0 10px 30px rgba(0,0,0,.4)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .fex-pg{--pg:var(--raised);--pg-fg:var(--fg);--pg-mut:var(--muted);--pg-line:var(--line);--pg-warn:240,168,48;--pg-wring:#f0a830;--pg-sh:0 0 0 1px var(--line),0 10px 30px rgba(0,0,0,.4)}}
.fex-pg .muted{color:var(--pg-mut)}
/* a label under the scan's tint or a highlight leans toward the ink, so it keeps 4.5:1 with any accent */
.fex-z:is(.scan,.hl) .muted{color:color-mix(in srgb,var(--pg-mut) 70%,var(--pg-fg))}
.fex-top{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px;font-size:13px}
.fex-z{position:relative;padding:2px var(--s-1);margin:0 -4px;border-radius:var(--r-xs);transition:background .3s,box-shadow .3s}
.fex-z.scan{background:color-mix(in srgb,var(--pg-hl) 8%,transparent)}
.fex-z.hl{background:color-mix(in srgb,var(--pg-hl) 12%,transparent);box-shadow:0 0 0 1.5px var(--pg-ring)}
.fex-z.warn.hl{background:rgba(var(--pg-warn),.14);box-shadow:0 0 0 1.5px var(--pg-wring)}
.fex-tb{border-top:1px solid var(--pg-line);border-bottom:1px solid var(--pg-line);padding:6px 0;display:flex;flex-direction:column;gap:var(--s-1)}
.fex-li{display:flex;justify-content:space-between;gap:10px}
.fex-tot{display:flex;justify-content:space-between;font-weight:500;font-size:13px}
.fex-smudge .num{filter:blur(.4px)}
.fex-beam{position:absolute;left:0;right:0;height:40px;background:linear-gradient(180deg,transparent,color-mix(in srgb,var(--pg-hl) 12%,transparent),transparent);pointer-events:none;top:-40px}
.fex-beam.go{animation:fexb 2.6s var(--ease-io) both}
@keyframes fexb{to{top:100%}}
.fex-side{padding:var(--s-3);display:flex;flex-direction:column;gap:var(--s-2);min-width:0}
.fex-sh{display:flex;justify-content:space-between;align-items:baseline;font-size:13px;padding:2px var(--s-1)}
.fex-sh b{font-weight:500}
.fex-st{font-size:12px}
.fex-list{display:flex;flex-direction:column;gap:2px;flex:1}
.fex-r{display:grid;grid-template-columns:70px 1fr auto;align-items:center;gap:var(--s-2);padding:7px 6px;border-radius:10px;font-size:13px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.fex-r:hover{background:var(--row)}}
.fex-r .k{font-size:12px;color:var(--muted)}
.fex-r .v{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;outline:0;border-radius:6px;padding:1px var(--s-1);margin:0 -4px}
.fex-r .v[contenteditable="true"]{background:var(--surface);box-shadow:0 0 0 1px var(--field-line)}
.fex-r .v[contenteditable="true"]:focus{box-shadow:0 0 0 1px var(--field-line-strong)}
.fex-cf{display:flex;align-items:center;gap:5px;font-size:11.5px;color:var(--muted)}
.fex-cf i{width:22px;height:4px;border-radius:2px;background:var(--line);overflow:hidden;display:block}
.fex-cf i b{display:block;height:100%;border-radius:2px;background:var(--ok);transform-origin:left;animation:ssrel .7s var(--ease) both}
.fex-r.warn .fex-cf i b{background:var(--warn)}
.fex-fix{font-size:12px;color:var(--warn);display:inline-flex;align-items:center;gap:var(--s-1)}
@keyframes ssrel{from{transform:scaleX(0)}}
.fex-f{display:flex;justify-content:flex-end}

DM.def('field-extraction', (r, c) => {
  const F = [['no','Invoice no.','NW-2041',.99],['date','Issued','2026-10-03',.97],['total','Total','$11,480.00',.98],['due','Due by','2026-11-1?',.41]];
  const list = $('.fex-list', r), st = $('.fex-st', r), go = $('.fex-go', r), doc = $('.fex-doc', r), pg = $('.fex-pg', r);
  const z = k => $(`.fex-z[data-z="${k}"]`, r);
  function row(f){
    const warn = f[3] < .6;
    const el = html(`<div class="fex-r${warn ? ' warn' : ''}" data-k="${f[0]}"><span class="k">${f[1]}</span><span class="v num">${f[2]}</span><span class="fex-cf">${warn ? `<button class="fex-fix" data-tip="${Math.round(f[3] * 100)}% sure, check it">${I('edit','xs')}Check</button>` : `<i><b style="width:${f[3] * 100}%"></b></i>${Math.round(f[3] * 100)}%`}</span></div>`);
    if (warn) z(f[0]).classList.add('warn');
    el.onmouseenter = () => z(f[0]).classList.add('hl'); el.onmouseleave = () => z(f[0]).classList.remove('hl');
    const fx = $('.fex-fix', el);
    if (fx) fx.onclick = () => { const v = $('.v', el); v.contentEditable = 'true'; v.textContent = '2026-11-1'; v.focus({ preventScroll:true }); const s = document.getSelection(); s.selectAllChildren(v); s.collapseToEnd(); z(f[0]).classList.add('hl'); swap(st, 'Type the day you see');
      const done = () => { v.contentEditable = 'false'; z(f[0]).classList.remove('hl', 'warn'); el.classList.remove('warn'); const cf = $('.fex-cf', el); cf.innerHTML = `<i><b style="width:100%"></b></i>Fixed`; enter(cf); go.disabled = false; swap(st, 'All fields confirmed'); };
      v.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); if (!/\d\d$/.test(v.textContent)) v.textContent = '2026-11-14'; done(); } }; v.onblur = () => { if (v.isContentEditable){ if (!/\d\d$/.test(v.textContent)) v.textContent = '2026-11-14'; done(); } }; };
    return el;
  }
  go.onclick = () => c.run(async () => { go.innerHTML = '<span class="spin"></span>'; await c.wait(800); go.innerHTML = I('check','xs') + 'Added to Invoices'; go.className = 'pill soft sm fex-go'; swap(st, '1 row added to Invoices 2026'); });
  c.run(async () => {
    const beam = html('<div class="fex-beam"></div>'); doc.appendChild(beam); await c.wait(300); beam.classList.add('go');
    for (const f of F){ await c.wait(560); const zz = z(f[0]); zz.classList.add('scan'); const el = row(f); list.appendChild(el); enter(el); c.later(500, () => zz.classList.remove('scan')); }
    await c.wait(400); swap(st, '1 field needs a look');
  });
});
